package com.thang.nihongo_user.controller;
import com.thang.nihongo_user.service.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import java.util.*;
@RestController @RequiredArgsConstructor
public class ClassroomController {
 private final ClassroomService classroom;
 public record PageView<T>(List<T> content,long totalElements,int number,int totalPages){static <T> PageView<T> from(Page<T> p){return new PageView<>(p.getContent(),p.getTotalElements(),p.getNumber(),p.getTotalPages());}}
 public record Archive(boolean archived,long version){}public record Publish(long version){}public record Members(List<String> ids){}
 private boolean admin(Jwt jwt){return jwt.getClaimAsStringList("roles").contains("ADMIN");}
 @GetMapping("/api/nihongo-user/staff/classrooms") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object list(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.list(jwt.getSubject(),admin(jwt),page));}
 @PostMapping("/api/nihongo-user/staff/classrooms") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object create(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ClassroomService.ClassInput input){return classroom.create(jwt.getSubject(),input);}
 @PutMapping("/api/nihongo-user/staff/classrooms/{id}") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object archive(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Archive input){return classroom.archive(jwt.getSubject(),admin(jwt),id,input.archived(),input.version());}
 @GetMapping("/api/nihongo-user/staff/classrooms/{id}/members") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object members(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.members(jwt.getSubject(),admin(jwt),id,page));}
 @PostMapping("/api/nihongo-user/staff/classrooms/{id}/members") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public void members(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Members input){classroom.addMembers(jwt.getSubject(),admin(jwt),id,input.ids());}
 @DeleteMapping("/api/nihongo-user/staff/classrooms/{id}/members/{userId}") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public void remove(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@PathVariable String userId){classroom.removeMember(jwt.getSubject(),admin(jwt),id,userId);}
 @GetMapping("/api/nihongo-user/staff/classrooms/{id}/assignments") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object assignments(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.assignments(jwt.getSubject(),admin(jwt),id,page));}
 @PostMapping("/api/nihongo-user/staff/classrooms/{id}/assignments") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object assign(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody ClassroomService.AssignmentInput input){return classroom.assign(jwt.getSubject(),admin(jwt),id,input);}
 @PostMapping("/api/nihongo-user/staff/assignments/{id}/publish") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object publish(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Publish input){return classroom.publish(jwt.getSubject(),admin(jwt),id,input.version());}
 @GetMapping("/api/nihongo-user/staff/assignments/{id}/results") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object results(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.results(jwt.getSubject(),admin(jwt),id,page));}
 @GetMapping("/api/nihongo-user/staff/attempts/{id}") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object inspect(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return classroom.inspect(jwt.getSubject(),admin(jwt),id);}
 @GetMapping("/api/nihongo-user/staff/attempts/{id}/feedback") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object feedback(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.feedback(jwt.getSubject(),true,admin(jwt),id,page));}
 @PostMapping("/api/nihongo-user/staff/attempts/{id}/feedback") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public Object feedback(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody ClassroomService.FeedbackInput input){return classroom.comment(jwt.getSubject(),admin(jwt),id,input);}
 @GetMapping("/api/nihongo-user/study/assignments") public Object mine(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.mine(jwt.getSubject(),page));}
 @PostMapping("/api/nihongo-user/study/assignments/{id}/start") public Object start(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return classroom.start(jwt.getSubject(),id);}
 @GetMapping("/api/nihongo-user/study/attempts/{id}") public Object read(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return classroom.read(jwt.getSubject(),id);}
 @PutMapping("/api/nihongo-user/study/attempts/{id}/answers") public Object save(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody ClassroomService.Answers input){return classroom.save(jwt.getSubject(),id,input,false);}
 @PostMapping("/api/nihongo-user/study/attempts/{id}/submit") public Object submit(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody ClassroomService.Answers input){return classroom.save(jwt.getSubject(),id,input,true);}
 @GetMapping("/api/nihongo-user/study/attempts/{id}/feedback") public Object mineFeedback(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestParam(defaultValue="0") int page){return PageView.from(classroom.feedback(jwt.getSubject(),false,false,id,page));}
}
